1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 台账文件已存在但没有任何内容（零字节，无论原本就是空文件还是使用中被截断）
31	// 时按损坏处理；已有台账文件无法读取、解析，存在两条配方编号与版本号
32	// 完全相同的配方记录，存在两条批次编号完全相同的批次记录，
33	// 任一配方版本的任一物料每份克数不是正数，
34	// 任一配方版本内同一物料编号出现多次，
35	// 任一批次绑定的配方版本未登记，
36	// 已保存投料的物料编号不属于该批次绑定的配方版本，
37	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
38	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
39	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
40	func Open(dir string) (*Store, error) {
41		if dir == "" {
42			return nil, errors.New("数据位置不能为空")
43		}
44		if err := os.MkdirAll(dir, 0o755); err != nil {
45			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
46		}
47		info, err := os.Stat(dir)
48		if err != nil {
49			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
50		}
51		if !info.IsDir() {
52			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
53		}
54	
55		lockPath := filepath.Join(dir, lockFileName)
56		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
57		if err != nil {
58			return nil, fmt.Errorf("打开锁文件失败: %w", err)
59		}
60	
61		s := &Store{dir: dir, lockFile: lf}
62		if err := s.load(); err != nil {
63			lf.Close()
64			return nil, err
65		}
66		return s, nil
67	}
68	
69	// Close 释放台账占用的文件锁。
70	func (s *Store) Close() error {
71		s.mu.Lock()
72		defer s.mu.Unlock()
73		if s.lockFile == nil {
74			return nil
75		}
76		err := s.lockFile.Close()
77		s.lockFile = nil
78		return err
79	}
80	
81	func (s *Store) lockExclusive() error {
82		if s.lockFile == nil {
83			return errors.New("台账已关闭")
84		}
85		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
86			return fmt.Errorf("锁定台账失败: %w", err)
87		}
88		return nil
89	}
90	
91	func (s *Store) lockShared() error {
92		if s.lockFile == nil {
93			return errors.New("台账已关闭")
94		}
95		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
96			return fmt.Errorf("锁定台账失败: %w", err)
97		}
98		return nil
99	}
100	
101	func (s *Store) unlock() {
102		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
103	}
104	
105	func (s *Store) load() error {
106		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
107		if err != nil {
108			if os.IsNotExist(err) {
109				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
110				return nil
111			}
112			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
113		}
114		if len(data) == 0 {
115			// 区分“没有台账文件”与“已有文件但内容为空”：文件不存在才算首次使用，
116			// 零字节文件（原本就为空或使用中被截断）一律按损坏处理——既不能当成
117			// 空台账补写，也不能凭内存中的旧记录还原，调用方必须明确知道无法读取。
118			return fmt.Errorf("%w: 台账文件 %q 没有内容", ErrCorruptData, filepath.Join(s.dir, stateFileName))
119		}
120		var st persistedState
121		if err := json.Unmarshal(data, &st); err != nil {
122			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
123		}
124		if st.Version != stateVersion {
125			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
126		}
127		if err := validateState(&st); err != nil {
128			return err
129		}
130		if st.Requests == nil {
131			st.Requests = map[string]*requestRecord{}
132		}
133		s.state = &st
134		return nil
135	}
136	
137	// validateState 检查台账的引用完整性与数量合法性：
138	//   - 配方由配方编号与版本号共同识别，同一台账内每组编号+版本号只能
139	//     对应一条配方记录。只要同组出现第二条记录，无论名称、物料、每份克数
140	//     是否相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或
141	//     最后一条、不能合并物料、也不能自行删除一条后继续——重复记录会让
142	//     查询结果与批次的应投依据取决于文件中的排列顺序。重复版本即使尚未
143	//     被任何批次引用也一样拒绝，其他配方与批次完整也不能放行本次读取。
144	//   - 批次由批次编号唯一识别，同一台账内一个编号只能对应一条批次记录。
145	//     同一编号出现第二条记录，无论绑定的配方版本、计划份数、状态是否
146	//     相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或最后
147	//     一条、不能合并投料、不能自动改号或删除一条后继续——重复记录会让
148	//     同一编号查到的配方、投料与数量核对取决于文件中的排列顺序。其他
149	//     批次完整、投料数量吻合，或调用方只想查看另一个正常批次，都不能
150	//     放行本次读取；不同编号的批次绑定同一配方版本不受影响。
151	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
152	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
153	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
154	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
155	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
156	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
157	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
158	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
159	//     不同版本、不同配方各自使用同一物料编号不受影响。
160	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
161	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
162	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
163	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
164	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
165	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
166	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
167	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
168	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
169	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
170	func validateState(st *persistedState) error {
171		// 先按“配方编号 + 版本号”唯一标识遍历全部配方记录：同组出现第二条
172		// 记录即数据损坏，必须先于一切按标识查找的校验拒绝——否则重复记录
173		// 会让 findRecipe 总是返回排在前面的一条，查询结果与批次应投依据都
174		// 取决于文件排列顺序。完全相同的内容也不是合法重复。
175		versions := make(map[recipeKey]bool, len(st.Recipes))
176		for _, r := range st.Recipes {
177			if r == nil {
178				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
179			}
180			key := recipeKey{r.RecipeNo, r.Version}
181			if versions[key] {
182				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方记录重复",
183					ErrCorruptData, r.RecipeNo, r.Version)
184			}
185			versions[key] = true
186		}
187		for _, r := range st.Recipes {
188			seen := make(map[string]bool, len(r.Materials))
189			for _, m := range r.Materials {
190				if seen[m.MaterialNo] {
191					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
192						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
193				}
194				seen[m.MaterialNo] = true
195				if m.GramsMilli <= 0 {
196					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
197						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
198				}
199			}
200		}
201		// 再按批次编号唯一标识遍历全部批次记录：同一编号出现第二条记录即数据
202		// 损坏，必须先于一切按编号查找的校验拒绝——否则 findBatch 总是返回排在
203		// 前面的一条，同一编号查到的配方、投料与数量核对都取决于文件排列顺序。
204		// 两条记录即使绑定不同配方版本、计划份数不同或状态不同也属于重复；
205		// 内容完全一致同样不是合法记录。不能挑第一条或最后一条、不能合并投料、
206		// 也不能自动改号或删除一条后继续。不同批次绑定同一配方版本不受影响。
207		batchNos := make(map[string]bool, len(st.Batches))
208		for _, b := range st.Batches {
209			if b == nil {
210				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
211			}
212			if batchNos[b.BatchNo] {
213				return fmt.Errorf("%w: 批次编号 %q 的批次记录重复", ErrCorruptData, b.BatchNo)
214			}
215			batchNos[b.BatchNo] = true
216		}
217		for _, b := range st.Batches {
218			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
219			if r == nil {
220				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
221					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
222			}
223			if err := validateFeedings(b, r); err != nil {
224				return err
225			}
226		}
227		return nil
228	}
229	
230	// validateFeedings 检查一个批次内已保存投料的合法性与配方归属。
231	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
232	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
233	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
234	// 在此拒绝。
235	func validateFeedings(b *batchRecord, r *recipeRecord) error {
236		acc := newFeedingAccumulator()
237		for _, f := range b.Feedings {
238			belongs := false
239			for _, m := range r.Materials {
240				if m.MaterialNo == f.MaterialNo {
241					belongs = true
242					break
243				}
244			}
245			if !belongs {
246				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
247					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
248			}
249			if f.GramsMilli <= 0 {
250				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
251					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
252			}
253			if !acc.add(f.MaterialNo, f.GramsMilli) {
254				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
255					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
256			}
257		}
258		return nil
259	}
260	
261	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
262	func (s *Store) persist(st *persistedState) error {
263		data, err := json.MarshalIndent(st, "", "  ")
264		if err != nil {
265			return err
266		}
267		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
268		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
269		if err != nil {
270			return err
271		}
272		if _, err := f.Write(data); err != nil {
273			f.Close()
274			return err
275		}
276		if err := f.Sync(); err != nil {
277			f.Close()
278			return err
279		}
280		if err := f.Close(); err != nil {
281			return err
282		}
283		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
284			return err
285		}
286		if d, err := os.Open(s.dir); err == nil {
287			_ = d.Sync()
288			_ = d.Close()
289		}
290		return nil
291	}
292	
293	func cloneState(st *persistedState) (*persistedState, error) {
294		data, err := json.Marshal(st)
295		if err != nil {
296			return nil, err
297		}
298		var out persistedState
299		if err := json.Unmarshal(data, &out); err != nil {
300			return nil, err
301		}
302		if out.Requests == nil {
303			out.Requests = map[string]*requestRecord{}
304		}
305		return &out, nil
306	}
307	
308	// write 是所有写入操作的统一入口：
309	//   - reqNo 为空直接报错；
310	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
311	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
312	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
313	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
314	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
315		if reqNo == "" {
316			return errors.New("请求编号不能为空")
317		}
318		s.mu.Lock()
319		defer s.mu.Unlock()
320		if err := s.lockExclusive(); err != nil {
321			return err
322		}
323		defer s.unlock()
324	
325		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
326		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
327		if err := s.load(); err != nil {
328			return err
329		}
330	
331		payloadRaw, err := json.Marshal(payload)
332		if err != nil {
333			return err
334		}
335		payloadStr := string(payloadRaw)
336	
337		if req, ok := s.state.Requests[reqNo]; ok {
338			if req.Op != op || req.Payload != payloadStr {
339				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
340					ErrRequestConflict, reqNo, req.Op, op)
341			}
342			if err := json.Unmarshal(req.Result, out); err != nil {
343				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
344			}
345			return nil
346		}
347	
348		clone, err := cloneState(s.state)
349		if err != nil {
350			return err
351		}
352		result, err := apply(clone)
353		if err != nil {
354			return err
355		}
356		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
357		if err := s.persist(clone); err != nil {
358			return fmt.Errorf("保存台账失败: %w", err)
359		}
360		s.state = clone
361		if err := json.Unmarshal(result, out); err != nil {
362			return fmt.Errorf("解析请求结果失败: %w", err)
363		}
364		return nil
365	}
366	
367	// read 在共享锁下读取当前状态。
368	func (s *Store) read(fn func(*persistedState) error) error {
369		s.mu.Lock()
370		defer s.mu.Unlock()
371		if err := s.lockShared(); err != nil {
372			return err
373		}
374		defer s.unlock()
375		if err := s.load(); err != nil {
376			return err
377		}
378		return fn(s.state)
379	}
380	
381	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
382	
383	func buildRecipeView(r *recipeRecord) *RecipeView {
384		mats := make([]MaterialView, 0, len(r.Materials))
385		for _, m := range r.Materials {
386			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
387		}
388		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
389	}
390	
391	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
392		v := &BatchView{
393			BatchNo:         b.BatchNo,
394			RecipeNo:        r.RecipeNo,
395			RecipeVersion:   r.Version,
396			RecipeName:      r.Name,
397			PlannedPortions: b.PlannedPortions,
398			Status:          b.Status,
399			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
400			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
401		}
402	
403		for _, f := range b.Feedings {
404			v.Feedings = append(v.Feedings, FeedingView{
405				Seq:        f.Seq,
406				MaterialNo: f.MaterialNo,
407				Grams:      f.GramsMilli.String(),
408				Time:       f.Time,
409				Registrar:  f.Registrar,
410			})
411		}
412	
413		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
414		// 这里仍用同一套累计规则防一手整数回绕。
415		acc := newFeedingAccumulator()
416		for _, f := range b.Feedings {
417			if !acc.add(f.MaterialNo, f.GramsMilli) {
418				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
419					ErrCorruptData, b.BatchNo, f.MaterialNo)
420			}
421		}
422	
423		// 数量核对按配方物料逐项列出；台账在读取时已通过 validateState 校验，
424		// 这里仍防一手同一版本内物料编号重复，避免返回重复的数量核对项。
425		seen := make(map[string]bool, len(r.Materials))
426		for _, m := range r.Materials {
427			if seen[m.MaterialNo] {
428				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
429					ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
430			}
431			seen[m.MaterialNo] = true
432			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
433			if err != nil {
434				return nil, fmt.Errorf("批次 %q 数量核对失败: %w", b.BatchNo, err)
435			}
436			act := acc.total(m.MaterialNo)
437			v.Materials = append(v.Materials, MaterialRequirement{
438				MaterialNo:      m.MaterialNo,
439				RequiredGrams:   required.String(),
440				ActualGrams:     act.String(),
441				DifferenceGrams: (act - required).String(),
442			})
443		}
444		return v, nil
445	}
446	
447	// recipeKey 是配方的唯一标识：配方编号与版本号的组合，采用精确匹配。
448	type recipeKey struct {
449		recipeNo string
450		version  string
451	}
452	
453	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
454		for _, r := range st.Recipes {
455			if r.RecipeNo == recipeNo && r.Version == version {
456				return r
457			}
458		}
459		return nil
460	}
461	
462	func findBatch(st *persistedState, batchNo string) *batchRecord {
463		for _, b := range st.Batches {
464			if b.BatchNo == batchNo {
465				return b
466			}
467		}
468		return nil
469	}
470

