66			}
67			b := &batchRecord{
68				BatchNo:         batchNo,
69				RecipeNo:        recipeNo,
70				RecipeVersion:   version,
71				PlannedPortions: portions,
72				Status:          StatusDraft,
73			}
74			view, err := buildBatchView(b, r)
75			if err != nil {
76				return nil, err
77			}
78			raw, err := json.Marshal(view)
79			if err != nil {
80				return nil, err
81			}
82			st.Batches = append(st.Batches, b)
83			return raw, nil
84		}, &out)
85		if err != nil {
86			return nil, err
87		}
88		return &out, nil
89	}
