1	package release
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	// 构造两条批次编号完全相同的批次记录；
15	// identical 为 true 时两条内容（配方版本、计划份数、状态）完全一致。
16	func batchDupRecords(identical bool) []*batchRecord {
17		first := &batchRecord{
18			BatchNo: "B1", RecipeNo: "R1", RecipeVersion: "v1",
19			PlannedPortions: 2, Status: StatusExecuting,
20		}
21		var second *batchRecord
22		if identical {
23			second = &batchRecord{
24				BatchNo: "B1", RecipeNo: "R1", RecipeVersion: "v1",
25				PlannedPortions: 2, Status: StatusExecuting,
26			}
27		} else {
28			second = &batchRecord{
29				BatchNo: "B1", RecipeNo: "R1", RecipeVersion: "v2",
30				PlannedPortions: 5, Status: StatusDraft,
31			}
32		}
33		return []*batchRecord{first, second}
34	}
35	
36	// Open 时只要存在两条批次编号完全相同的批次记录就必须返回 ErrCorruptData：
37	// 绑定不同配方版本、份数与状态不同、内容完全一致，三种情形都拒绝；
38	// 错误信息需包含重复的批次编号；不返回可用的台账对象，也不改写原文件；
39	// 不得挑第一条或最后一条、合并投料、自动改号或删除一条后放行。
40	func TestOpenRejectsDuplicateBatch(t *testing.T) {
41		cases := []struct {
42			name      string
43			identical bool
44		}{
45			{"绑定不同配方版本份数状态不同", false},
46			{"两条记录内容完全一致", true},
47		}
48		for _, tc := range cases {
49			t.Run(tc.name, func(t *testing.T) {
50				dir := t.TempDir()
51				st := &persistedState{
52					Version: stateVersion,
53					Recipes: []*recipeRecord{
54						recipeR1v1(),
55						{RecipeNo: "R1", Version: "v2", Name: "配方一 v2",
56							Materials: []materialRecord{{MaterialNo: "M1", GramsMilli: 200000}}},
57					},
58					Batches: batchDupRecords(tc.identical),
59				}
60				original := writeStateFile(t, dir, st)
61	
62				s, err := Open(dir)
63				if !errors.Is(err, ErrCorruptData) {
64					t.Fatalf("重复批次编号应返回 ErrCorruptData，得到 %v", err)
65				}
66				if s != nil {
67					s.Close()
68					t.Fatalf("损坏台账不应返回可用的 Store 对象")
69				}
70				if !strings.Contains(err.Error(), "B1") {
71					t.Fatalf("错误信息应包含重复的批次编号 %q，得到 %v", "B1", err)
72				}
73				// 原台账内容保留：不得挑一条、合并投料、改号或删除一条后另存。
74				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
75				if err != nil {
76					t.Fatal(err)
77				}
78				if !bytes.Equal(got, original) {
79					t.Fatalf("拒绝打开不应改动台账文件")
80				}
81			})
82		}
83	}
84	
85	// 台账里其他批次完整、重复批次各自的投料数量也与配方吻合，同样不能放行：
86	// 只要一个批次编号对应两条记录，Open 整体失败。
87	func TestOpenDuplicateBatchAmongCompleteRecords(t *testing.T) {
88		dir := t.TempDir()
89		dups := batchDupRecords(false)
90		// 让两条重复记录各自的投料都与绑定配方吻合，排除“数量不符”这条拒绝理由。
91		dups[0].Feedings = []feedingRecord{
92			{Seq: 1, MaterialNo: "M1", GramsMilli: 200000, Registrar: "张三"},
93		}
94		dups[1].Feedings = []feedingRecord{
95			{Seq: 1, MaterialNo: "M1", GramsMilli: 1000000, Registrar: "李四"},
96		}
97		writeStateFile(t, dir, &persistedState{
98			Version: stateVersion,
99			Recipes: []*recipeRecord{
100				recipeR1v1(),
101				{RecipeNo: "R1", Version: "v2", Name: "配方一 v2",
102					Materials: []materialRecord{{MaterialNo: "M1", GramsMilli: 200000}}},
103			},
104			Batches: append([]*batchRecord{
105				{BatchNo: "B-ok", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 1, Status: StatusClosed},
106			}, dups...),
107		})
108		if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
109			t.Fatalf("其他批次完整、投料吻合也应整体拒绝，得到 %v", err)
110		}
111	}
112	
113	// 台账打开后本地文件被改坏（多出一条相同批次编号的记录）：
114	// 下一次查询或写入都必须返回 ErrCorruptData，即使查询的是另一个正常批次；
115	// 不得凭此前读取过的内容返回旧结果，也不能用保存的请求结果绕过本次损坏；
116	// 被拒绝的写入不留业务记录、不占用请求编号；恢复后原记录继续可用。
117	func TestDuplicateBatchAfterOpenDetectedOnNextAccess(t *testing.T) {
118		dir := t.TempDir()
119		s, err := Open(dir)
120		if err != nil {
121			t.Fatal(err)
122		}
123		defer s.Close()
124	
125		if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
126			{MaterialNo: "M1", Grams: "100"},
127		}); err != nil {
128			t.Fatal(err)
129		}
130		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 2); err != nil {
131			t.Fatal(err)
132		}
133		if _, err := s.StartBatch("s1", "B1"); err != nil {
134			t.Fatal(err)
135		}
136		fixedTime := time.Date(2026, 8, 1, 9, 0, 0, 0, time.UTC)
137		if _, err := s.AddFeeding("feed-1", "B1", "M1", "50", fixedTime, "张三"); err != nil {
138			t.Fatal(err)
139		}
140		// 另一个完全正常的批次，用于验证“只想查看正常批次”同样被拒绝。
141		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 1); err != nil {
142			t.Fatal(err)
143		}
144	
145		// 保存完好时的文件内容，随后追加一条编号同样为 B1 的批次记录。
146		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
147		if err != nil {
148			t.Fatal(err)
149		}
150		var broken persistedState
151		if err := json.Unmarshal(good, &broken); err != nil {
152			t.Fatal(err)
153		}
154		broken.Batches = append(broken.Batches, &batchRecord{
155			BatchNo: "B1", RecipeNo: "R1", RecipeVersion: "v1",
156			PlannedPortions: 9, Status: StatusDraft,
157		})
158		badBytes := writeStateFile(t, dir, &broken)
159	
160		// 查询：重复编号、另一个正常批次，全部失败；
161		// 不能凭此前读取过的内容返回旧结果。
162		if _, err := s.GetBatch("B1"); !errors.Is(err, ErrCorruptData) {
163			t.Fatalf("文件损坏后查询重复批次应返回 ErrCorruptData，得到 %v", err)
164		}
165		if _, err := s.GetBatch("B2"); !errors.Is(err, ErrCorruptData) {
