167		}
168		if _, err := s.GetRecipe("R1", "v1"); !errors.Is(err, ErrCorruptData) {
169			t.Fatalf("即使只查询配方也必须拒绝，得到 %v", err)
170		}
171	
172		// 写入：投料、关闭、调整、新建批次、登记配方都必须被拒绝。
173		if _, err := s.AddFeeding("feed-rejected", "B1", "M1", "1", time.Now(), "李四"); !errors.Is(err, ErrCorruptData) {
174			t.Fatalf("损坏台账上投料应返回 ErrCorruptData，得到 %v", err)
175		}
