199		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
200		if err != nil {
201			t.Fatal(err)
202		}
203		if !bytes.Equal(after, badBytes) {
204			t.Fatalf("被拒绝的写入不应改动台账文件")
205		}
