232		}
233		// 被拒绝过的请求编号仍可用于合法提交。
234		f, err := s.AddFeeding("feed-rejected", "B1", "M1", "1", time.Now(), "李四")
235		if err != nil {
236			t.Fatalf("被拒绝的请求编号应仍可合法使用: %v", err)
