242	
243	// 不同编号的批次绑定同一配方版本是合法组合，正常创建、查询，
244	// 数量核对按各自批次的计划份数计算，不能被误判为重复。
245	func TestOpenAllowsDifferentBatchesSharingRecipeVersion(t *testing.T) {
246		dir := t.TempDir()
247		s, err := Open(dir)
248		if err != nil {
249			t.Fatal(err)
250		}
251		defer s.Close()
252	
253		if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
254			{MaterialNo: "M1", Grams: "100"},
255		}); err != nil {
