262			t.Fatal(err)
263		}
264		for _, want := range []struct {
265			batchNo  string
266			required string
267		}{
268			{"B1", "200"},
269			{"B2", "300"},
270		} {
271			b, err := s.GetBatch(want.batchNo)
272			if err != nil {
273				t.Fatalf("查询批次 %q 失败: %v", want.batchNo, err)
274			}
275			if b.Materials[0].RequiredGrams != want.required {
276				t.Fatalf("批次 %q 应投量应按各自份数计算，得到 %+v", want.batchNo, b.Materials)
277			}
278		}
279	
280		// 重新打开仍应正常。
281		if err := s.Close(); err != nil {
