290			t.Fatalf("共用配方版本的不同批次应可正常查询: %v", err)
291		}
292	}
293	
294	// 通过正常创建入口再次创建已存在的批次仍按普通冲突处理
295	// （ErrDuplicateBatch），不能与文件损坏的 ErrCorruptData 混用；
296	// 完整台账上重复提交同一请求编号与相同内容，仍返回第一次成功的
297	// 结果，不产生第二条批次；失败不占用请求编号。
298	func TestCreateBatchExistingStillDuplicateBatch(t *testing.T) {
299		dir := t.TempDir()
300		s, err := Open(dir)
301		if err != nil {
302			t.Fatal(err)
303		}
304		defer s.Close()
305	
306		if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
307			{MaterialNo: "M1", Grams: "100"},
308		}); err != nil {
309			t.Fatal(err)
310		}
311		first, err := s.CreateBatch("b1", "B1", "R1", "v1", 2)
312		if err != nil {
313			t.Fatal(err)
314		}
315	
316		// 新请求编号创建已存在的批次：ErrDuplicateBatch，且失败不占号。
317		_, err = s.CreateBatch("b1-again", "B1", "R1", "v1", 2)
318		if !errors.Is(err, ErrDuplicateBatch) {
319			t.Fatalf("重复创建应返回 ErrDuplicateBatch，得到 %v", err)
320		}
321		if errors.Is(err, ErrCorruptData) {
322			t.Fatalf("普通创建冲突不应归为数据损坏，得到 %v", err)
323		}
324		if _, err := s.CreateBatch("b1-again", "B9", "R1", "v1", 1); err != nil {
325			t.Fatalf("被拒绝的请求编号应仍可合法使用: %v", err)
326		}
327	
328		// 同一请求编号与相同内容重复提交：返回第一次成功的结果。
329		replay, err := s.CreateBatch("b1", "B1", "R1", "v1", 2)
330		if err != nil {
331			t.Fatalf("幂等重放应成功: %v", err)
332		}
333		if replay.BatchNo != first.BatchNo || replay.PlannedPortions != first.PlannedPortions {
334			t.Fatalf("重放应返回第一次成功的结果，得到 %+v", replay)
335		}
336	
337		// 台账中 B1 仍只有一条记录。
338		var st persistedState
339		data, err := os.ReadFile(filepath.Join(dir, stateFileName))
340		if err != nil {
341			t.Fatal(err)
342		}
343		if err := json.Unmarshal(data, &st); err != nil {
344			t.Fatal(err)
345		}
346		count := 0
347		for _, b := range st.Batches {
348			if b.BatchNo == "B1" {
349				count++
350			}
351		}
352		if count != 1 {
353			t.Fatalf("批次 B1 应只有一条记录，得到 %d 条", count)
354		}
